#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.."&&pwd)";SOURCE="${BIBZCODE_CODEOSS_SOURCE:-$ROOT/.work/vscode}";RELEASE="${BIBZCODE_CODEOSS_RELEASE:-$ROOT/release}";BUILD_ROOT="$(dirname "$SOURCE")";[[ "$(uname -s)" == Darwin && -d "$BUILD_ROOT/VSCode-darwin-x64" && -d "$BUILD_ROOT/VSCode-darwin-arm64" ]]||exit 2;mkdir -p "$RELEASE";export VSCODE_ARCH=universal VSCODE_QUALITY="${VSCODE_QUALITY:-stable}" NODE_OPTIONS="${NODE_OPTIONS:---max-old-space-size=8192}";cd "$SOURCE";node build/darwin/create-universal-app.ts "$BUILD_ROOT";APP_ROOT="$BUILD_ROOT/VSCode-darwin-universal";APP_NAME="$(find "$APP_ROOT" -maxdepth 1 -type d -name '*.app' -exec basename {} \;|head -1)";[[ -n "$APP_NAME" ]]||exit 1;APP_PATH="$APP_ROOT/$APP_NAME" node build/darwin/verify-macho.ts universal;(cd "$APP_ROOT"&&zip -q -r -X -y "$RELEASE/BibzCode-IDE-7.8.0-r6-mac-universal.zip" "$APP_NAME");node build/darwin/create-dmg.ts "$BUILD_ROOT" "$RELEASE";DMG="$(find "$RELEASE" -maxdepth 1 -type f -name '*.dmg'|head -1)";[[ -z "$DMG" ]]||mv "$DMG" "$RELEASE/BibzCode-IDE-7.8.0-r6-mac-universal.dmg";cd "$RELEASE";find . -maxdepth 1 -type f ! -name SHA256SUMS -print0|sort -z|xargs -0 shasum -a 256>SHA256SUMS;cat SHA256SUMS
